INSERT INTO public.poems (id, title, content, position, is_example, created_at, view_count)
VALUES (9, E'O Que Permanece Depois das Conquistas', E'Viemos da perfeição. Isso não significa que sejamos perfeitos. Longe disso.\n\nOlhemos para o que está escrito, para aquilo que aconteceu e continua a se repetir diante dos nossos olhos.\n\nDesde a criação, o homem parece viver como o ferro em transformação: nasce, é moldado pelas circunstâncias, cresce, conquista posições e, por vezes, chega a ser coroado. Em seus domínios, estabelece fronteiras, divide territórios e acumula riquezas.\n\nMas, quando o poder chega às suas mãos, muitas vezes nasce também a ambição por novas conquistas.\n\nMesmo possuindo grandes riquezas e dominando quase tudo o que existe em seu território, o homem avança sobre o domínio de outros. Reis enfrentam reis, conquistadores enfrentam conquistadores, e, geração após geração, novos vencedores são anunciados.\n\nMas vencedores de quê?\n\nAté onde pretendem chegar? E o que realmente levam consigo?\n\nOlhemos para os lugares onde essas disputas aconteceram. As riquezas continuam ali. O ouro continua sendo ouro, os minerais permanecem minerais, e a terra continua sendo terra. As fronteiras podem mudar, os territórios podem trocar de mãos e os nomes dos donos podem desaparecer, mas a matéria permanece.\n\nAfinal, o que mudou de verdade?\n\nO homem desafiou, com sua arrogância, aquilo que não podia transformar à sua vontade. Lutou para possuir o que já existia, destruiu para dominar e, nessa busca incessante, deixou para trás outras conquistas que poderia ter alcançado.\n\nPoderia ter progredido em família, fortalecido a cooperação, compartilhado conhecimentos e construído um crescimento capaz de beneficiar a todos. Poderia ter aprendido que a união também é uma forma de conquista e que nem toda vitória precisa produzir vencidos.\n\nMas, enquanto disputava territórios, quantas oportunidades de construir uma humanidade melhor foram perdidas?\n\nE assim chegamos aos dias de hoje, repetindo antigas disputas, acumulando prejuízos e deixando marcas profundas na natureza. Aquilo que recebemos como uma criação perfeita já não se encontra nas mesmas condições. O homem conquistou espaços, mas também feriu a própria casa.\n\nSerá que era esse o propósito?\n\nE aqui chego ao ponto que considero mais importante.\n\nEntre tantos que sofreram as consequências dessas disputas, existem aqueles que permaneceram fiéis aos propósitos para os quais acreditam ter sido criados. Pessoas que compreenderam que a verdadeira conquista não está em dominar o mundo, mas em transformar a si mesmas; não em acumular riquezas, mas em preservar aquilo que possui valor para além delas.\n\nÉ nessa transformação que encontro a ideia da purificação dos seres, da preservação da essência vital e do retorno à perfeição.\n\nPorque, se as conquistas materiais passam de umas mãos para outras, o que dizer daquilo que construímos dentro de nós?\n\nSe os reis desaparecem e seus domínios mudam de donos, o que poderá permanecer além do tempo?\n\nPara mim, a maior vitória de todas não está em vencer outros homens, conquistar suas terras ou tomar suas riquezas. Está em permanecer fiel ao Criador, respeitar os propósitos da criação e cuidar da essência que dá sentido à nossa existência.\n\nTalvez o homem passe séculos tentando conquistar o mundo sem perceber que a conquista mais importante começa dentro de si.\n\nE talvez seja essa a grande diferença entre possuir algo por algum tempo e preparar-se para aquilo que, pela fé, acreditamos ser eterno.\n\nPois as riquezas podem mudar de mãos, os territórios podem mudar de fronteiras e as gerações podem desaparecer.\n\nMas a essência purificada, aquela que permanece fiel ao Criador, representa, na minha compreensão, a maior vitória que um ser pode alcançar.\n\nPorque não basta conquistar o mundo.\n\nÉ preciso compreender para que fomos criados.\n\nE somente com temor ao Criador, fidelidade aos seus propósitos e transformação da nossa essência poderemos aspirar à vida eterna.', 9, FALSE, TIMESTAMPTZ '2026-10-02T23:19:06.163692+00:00', 9);

INSERT INTO public.poems (id, title, content, position, is_example, created_at, view_count)
VALUES (10, E'As Pegadas que Eu Não Notei', E'Hoje, pai, a ti peço perdão. \n\nTudo aquilo que pensei,\ntudo aquilo que me foi mostrado por ti,\nignorei.\n\nNas estradas da vida, escolhi aquelas\nque talvez não escolhesses para mim.\n\nAs portas que se abriram,\nmuitas delas eu não desejei.\n\nPassei por onde, às vezes, poucos andam.\n\nPisei em espinhos que tentaram impedir minha passagem.\n\nSenti o sol como se fosse uma brasa\ne, enquanto ele dourava minha pele,\ntalvez me fizesse um pedido de desculpas\nque eu não soube perceber.\n\nChuva, ventos, tempestades...\ndeles me agasalhava em teus braços,\nsem saber.\n\nO tempo passou depressa,\ncomo nuvens que vêm e vão.\n\nMas, por mais que tentassem me mudar,\neu resisti,\nporque tenho princípios.\n\nE esses princípios são raízes profundas,\npor onde corre a seiva\nque chega ao caule, às folhas e aos frutos,\npreparando a árvore para saudar a vida.\n\nMesmo quando me distraí pelo caminho...\n\nPorque Ele ama a todos,\ncada um do seu jeito,\nsem molduras,\napenas mostrando-se\na cada janela que se deixa abrir\npara o vento entrar.\n\nHoje, olho para a vida\ne para onde ela me levou.\n\nVejo as marcas dos meus pés\npor onde passei.\n\nE, ao lado delas,\nsempre estiveram outras pegadas...\n\nPegadas que eu não notei.', 8, FALSE, TIMESTAMPTZ '2026-10-02T23:43:39.400602+00:00', 2);

INSERT INTO public.poems (id, title, content, position, is_example, created_at, view_count)
VALUES (11, E'A cor do invisível', E'Nasci despojado de tudo. Nasci nu.\n\nFui acolhido e vestido com muito amor. Cresci, mas ainda não abri meus olhos.\n\nMinha boca só recebe o necessário. Pouco ligo para minhas vestes. Apenas escuto, sempre muito atento aos mínimos detalhes.\n\nAprendi, mesmo sem olhar, a perceber os sentidos, os sentimentos, a verdade e as coisas ocultas. Aprendi a distinguir passos verdadeiros de passos falsos.\n\nAprendi a sentir o amor verdadeiro.\n\nSeparei tudo o que havia aprendido e me preparei para abrir meus olhos.\n\nEnquanto esperava, imaginei todas as coisas, principalmente as cores.\n\nImaginei o sol.\n\nImaginei a lua.\n\nImaginei a cor da água.\n\nE o vento? Seria visível?\n\nSe pudesse ser visto, qual seria a sua cor?\n\nTalvez fosse a cor do invisível.\n\nMas essa cor eu não sei e talvez nunca saberei.\n\nMesmo assim, continuei imaginando.\n\nImaginava o mundo sem vê-lo. Criava paisagens dentro de mim, inventava cores para aquilo que nunca havia tocado com os olhos e dava formas ao que só conhecia pelos sons, pelos cheiros, pelo calor, pelo frio e pelos sentimentos.\n\nE, quanto mais eu imaginava, mais percebia que havia coisas que os olhos talvez não fossem capazes de mostrar.\n\nHavia passos que diziam muito antes que uma palavra fosse pronunciada.\n\nHavia silêncios que falavam.\n\nHavia mãos que acolhiam e outras que escondiam intenções.\n\nHavia sorrisos que pareciam bondosos, mas carregavam alguma coisa que eu não sabia explicar.\n\nEu não via os rostos.\n\nMas percebia.\n\nTalvez o mundo fosse muito maior do que aquilo que meus olhos poderiam me mostrar.\n\nE então continuei esperando o dia em que finalmente abriria meus olhos.\n\nQueria descobrir se o sol era realmente da cor que imaginei, se a lua tinha a beleza que construí dentro de mim, se a água era azul ou se apenas havia escolhido essa cor porque era assim que eu desejava enxergá-la.\n\nQueria descobrir se o vento possuía alguma cor.\n\nQueria descobrir a cor do invisível.\n\nMas algumas coisas eu já havia descoberto.\n\nAs pegadas falsas.\n\nO sorriso malicioso.\n\nA voz que mudava quando escondia alguma intenção.\n\nO silêncio que dizia mais do que muitas palavras.\n\nTudo isso descobri de olhos fechados.\n\nTalvez, quando finalmente os abrir, eu descubra que algumas das coisas mais importantes da vida nunca tiveram cor.\n\nE que aquilo que eu mais queria enxergar talvez já estivesse diante de mim.\n\nEu apenas aprendi a perceber antes de ver.', 7, FALSE, TIMESTAMPTZ '2026-10-02T23:53:15.39126+00:00', 2);

INSERT INTO public.poems (id, title, content, position, is_example, created_at, view_count)
VALUES (12, E'Eu estou buscando a paz.', E'Sei lá onde irei encontrá-la.\n\nSe for preciso virar pedra, ah, eu viro.\n\nSe eu a enxergar, só isso já basta.\n\nVou procurar debaixo das pontes.\nAli sempre tem alguém descansando.\n\nPode ser gente, um peixe,\ntalvez um bicho qualquer.\n\nSe a paz estiver ali,\nvou perguntar qual é o segredo dela.\n\nQuanto custa para atingir esse nível?\nSerá que existem medidas para isso?\n\nE o gosto da paz,\nqual seria?\n\nDoce como o mel?\nLeve como o vento?\nOu simplesmente silencioso,\ncomo aquele instante em que nada mais precisa ser dito?\n\nMas primeiro preciso encontrá-la.\n\nMeus pés já estão cansados.\nMinhas roupas estão gastas.\nSem falar da fome e da sede.\n\nMas sei que a sede maior\né pela paz.\n\nE, quando eu finalmente encontrá-la,\nnão quero guardá-la só para mim.\n\nVou distribuí-la.\n\nVou levá-la para aqueles que ainda querem a guerra,\npara os que acreditam que a violência resolve,\npara os que não sossegam enquanto não conquistam fama e poder.\n\nTalvez alguns não queiram recebê-la.\n\nMesmo assim, deixarei um pouco pelo caminho.\n\nQuem sabe alguém, um dia,\ntenha sede e encontre.\n\nPorque a paz não deveria ser propriedade de ninguém.\n\nEla deveria ser como a água:\nquando existe, deve alcançar quem tem sede.\n\nE só depois disso,\nquando eu tiver encontrado a paz\ne ajudado outros a encontrá-la também,\n\nvou vestir minhas vestes\nde uma pessoa feliz.', 6, FALSE, TIMESTAMPTZ '2026-10-03T15:26:58.548558+00:00', 2);

INSERT INTO public.poems (id, title, content, position, is_example, created_at, view_count)
VALUES (14, E'A Semente da Nova Humanidade', E'No final dos tempos, quando quase tudo tivesse sido destruído pelas próprias mãos humanas, talvez os frutos da terra fossem aquilo que ainda poderia salvar a Terra.\nPouco teria restado.\nFlorestas inteiras desapareceriam, rios perderiam suas forças, animais deixariam de ocupar lugares onde durante milhares de anos haviam vivido, e muitas espécies existiriam apenas nas lembranças daqueles que conheceram o mundo de antes.\nTalvez ainda houvesse vida.\nMas isso seria apenas um talvez.\nBem no interior de um lugar onde ninguém imaginava chegar, existiria uma pequena comunidade de sobreviventes.\nSeriam poucas pessoas.\nHomens, mulheres, idosos e crianças.\nPessoas de diferentes idades, reunidas não porque tivessem escolhido aquele lugar, mas porque o destino havia deixado para elas uma última oportunidade.\nElas sabiam o que havia acontecido.\nSabiam que a destruição não tinha vindo de uma única catástrofe.\nDurante muito tempo, a humanidade havia guerreado por territórios, riquezas e poder.\nReis quiseram mais terras.\nGovernantes quiseram mais domínio.\nHomens acumularam riquezas enquanto outros não tinham o necessário para viver.\nFlorestas foram derrubadas.\nRios foram contaminados.\nE, muitas vezes, aquilo que poderia ter sido compartilhado tornou-se motivo de disputa.\nCada geração dizia que aprenderia com os erros da anterior.\nMas muitas continuavam repetindo os mesmos erros.\nAgora, porém, aqueles poucos sobreviventes tinham diante de si uma escolha diferente.\nNão possuíam grandes riquezas.\nNão possuíam exércitos.\nNão possuíam palácios.\nPossuíam sementes.\nSementes de árvores.\nSementes de plantas.\nSementes de alimentos.\nE, em pequenos espaços protegidos, alguns animais que haviam conseguido sobreviver.\nTalvez aquilo fosse tudo o que restava da antiga abundância.\nE eles compreenderam que não poderiam simplesmente reconstruir o mundo antigo.\nPrecisariam construir outro.\nComeçaram então a cultivar.\nCada semente recebia cuidado.\nCada árvore que nascia era uma promessa.\nCada animal que conseguia sobreviver era tratado como parte de uma história que não poderia ser perdida novamente.\nAs crianças aprendiam os nomes das espécies.\nOs adultos aprendiam a cuidar da terra.\nOs mais velhos contavam o que havia acontecido antes.\nNão contavam as histórias para alimentar o ódio contra os que viveram no passado.\nContavam para que os erros não voltassem a nascer.\nE havia uma regra que todos precisavam compreender:\nninguém seria dono daquilo que pertencia à vida.\nNão haveria um rei acima dos outros.\nNão haveria alguém escolhido para possuir mais terra porque se considerava mais importante.\nNão haveria um homem capaz de decidir sozinho quem poderia viver ou quem deveria morrer.\nAs decisões seriam tomadas em conjunto.\nA terra seria cultivada por todos.\nAs sementes seriam preservadas para todos.\nOs animais seriam protegidos por todos.\nE, quando alguma criança perguntasse:\n— Quem é o dono desta terra?\nOs mais velhos responderiam:\n— Ninguém.\nDepois diriam:\n— Nós apenas estamos cuidando dela enquanto ela estiver sob nossas mãos.\nAlguns anos se passaram.\nA pequena comunidade cresceu, e entre os jovens surgiu um rapaz de inteligência extraordinária.\nEle aprendia rapidamente, encontrava soluções para muitos problemas e começou a acreditar que, por saber mais do que os outros, talvez merecesse alguns benefícios particulares.\nNão queria destruir a comunidade.\nNão queria fazer uma guerra.\nQueria apenas algumas vantagens que, segundo ele, seriam merecidas por sua inteligência.\nOs mais experientes ouviram suas ideias com atenção.\nNão o humilharam.\nNão disseram que sua inteligência não tinha valor.\nPelo contrário, reconheceram suas capacidades.\nMas também lhe mostraram algo que o passado já havia ensinado da maneira mais dolorosa:\nfoi assim que muitas diferenças começaram.\nPrimeiro alguém acreditava merecer um pouco mais.\nDepois outro queria mais poder.\nMais tarde alguém acreditava ser superior.\nE, quando perceberam, já existiam aqueles que mandavam e aqueles que obedeciam, aqueles que possuíam e aqueles que nada tinham.\nUm dos mais velhos então lhe disse:\n— Sua inteligência é uma grande contribuição para todos, mas ela não faz de você alguém maior do que os outros. Se você usar aquilo que sabe para ajudar, todos cresceremos. Se usar para obter privilégios sobre os demais, estaremos começando novamente a história que quase destruiu a humanidade.\nO jovem ficou em silêncio.\nPela primeira vez, percebeu que ser diferente em uma habilidade não significava possuir um valor maior como ser humano.\nEle compreendeu que todos tinham capacidades diferentes, mas nenhum deles deveria ser considerado mais humano que o outro.\nE assim aquela comunidade aprendeu mais uma vez que ninguém era mais do que ninguém.\nTodos tinham o mesmo valor.\nA inteligência de um poderia servir ao conhecimento de todos.\nA força de outro poderia servir ao trabalho de todos.\nA experiência dos mais velhos poderia orientar os mais jovens.\nE a curiosidade das crianças poderia abrir caminhos que os adultos ainda não haviam imaginado.\nTalvez essa fosse a maior lição que o passado poderia deixar.\nDurante séculos, o homem havia confundido posse com permanência.\nPensava que conquistar uma terra significava tê-la para sempre.\nMas os reis morreram.\nOs impérios desapareceram.\nAs fronteiras mudaram.\nAs riquezas trocaram de mãos.\nE a Terra continuou ali.\nAgora aqueles sobreviventes sabiam que não precisavam ser donos do mundo.\nPrecisavam apenas não destruí-lo novamente.\nCom o passar dos anos, as árvores cresceram.\nOs frutos começaram a aparecer.\nOs animais se reproduziram.\nOs rios voltaram a encontrar pequenos caminhos.\nA vida começou, lentamente, a ocupar espaços que antes pareciam mortos.\nE então perceberam algo que talvez os antigos nunca tivessem compreendido completamente:\na Terra não precisava de um novo conquistador.\nPrecisava de cuidadores.\nO maior progresso daquela nova humanidade não seria construir cidades maiores, acumular riquezas ou levantar monumentos.\nSeria conseguir chegar ao futuro sem destruir o presente.\nE talvez, quando uma criança daquela pequena comunidade segurasse uma semente entre as mãos e perguntasse:\n— O que vai nascer daqui?\nAlguém pudesse responder:\n— Depende do que aprendemos com o que morreu.\nPorque aquela semente não carregava apenas uma árvore.\nCarregava uma escolha.\nRepetir o passado.\nOu começar outra história.\nE talvez fosse essa a última oportunidade da humanidade:\nnão conquistar novamente a Terra,\nmas aprender, finalmente, a viver nela.', 4, FALSE, TIMESTAMPTZ '2026-10-03T15:38:30.312218+00:00', 0);

INSERT INTO public.poems (id, title, content, position, is_example, created_at, view_count)
VALUES (15, E'Somos como grãos de uma uva.', E'Quando caímos, muitas vezes parecemos vencidos. Somos pisoteados pelas circunstâncias, esmagados pelas dificuldades e, por alguns instantes, podemos acreditar que aquela é a nossa derrota definitiva.\n\nMas nem sempre aquilo que parece o fim é realmente o fim.\n\nDentro de cada grão existe uma semente. E, quando encontra uma terra fértil, ela começa silenciosamente a fazer aquilo que sabe fazer: germinar.\n\nA chuva pode cair sobre ela, o sol pode aquecer a terra, o vento pode passar por cima, e ninguém talvez perceba o que está acontecendo debaixo da superfície. Até que, um dia, surge um pequeno sinal de vida.\n\nUma raiz.\n\nDepois, um caule.\n\nDepois, folhas.\n\nE aquilo que parecia ter sido destruído começa novamente a crescer.\n\nAssim também somos nós.\n\nA vida nos derruba de muitas maneiras. Há quedas que acontecem diante dos olhos de todos e outras que somente nós conhecemos. Há derrotas que deixam cicatrizes no corpo e outras que permanecem escondidas dentro da alma. Há caminhos que nos fazem perder tempo, pessoas que nos deixam marcas, sonhos que não se realizam e portas que se fecham justamente quando mais desejávamos atravessá-las.\n\nMesmo assim, insistimos.\n\nExiste no ser humano uma espécie de valentia silenciosa que não faz barulho. É aquela força que nos faz levantar quando ninguém mais acredita que conseguiremos. É acordar depois de uma noite difícil e, mesmo sem saber exatamente para onde ir, continuar caminhando.\n\nÉ teimar em viver.\n\nTeimar em procurar.\n\nTeimar em acreditar que ainda pode existir um amanhã diferente.\n\nCorremos atrás da felicidade como quem procura uma terra onde finalmente possa fincar raízes. Experimentamos caminhos, construímos sonhos, perdemos alguns deles e reconstruímos outros. Às vezes pensamos que a felicidade está em algum lugar distante, quando ela pode estar justamente naquilo que ainda não aprendemos a enxergar.\n\nE continuamos procurando.\n\nAté que, em algum momento da caminhada, podemos encontrar alguém que parece completar uma parte de nós que ainda estava silenciosa.\n\nNão porque sejamos incompletos sozinhos, mas porque existem encontros que dão outro sentido à caminhada.\n\nDuas histórias se encontram. Duas experiências diferentes, duas coleções de cicatrizes, dois caminhos que até então seguiam separados passam a caminhar lado a lado.\n\nE então a busca pode começar a sossegar.\n\nJá não é preciso correr tanto.\n\nÉ hora de procurar um lugar, construir um abrigo, criar raízes e, talvez, formar uma família. Não apenas para encontrar companhia, mas para dar continuidade àquilo que recebemos da vida e àquilo que ainda podemos deixar para quem virá depois de nós.\n\nAssim, a semente volta a cumprir seu destino.\n\nO fruto cai, carrega dentro de si novas sementes e, mesmo quando parece que tudo terminou, alguma coisa continua.\n\nTalvez seja essa uma das maiores valentias do ser humano: compreender que sua passagem pela vida não precisa terminar nele.\n\nPodemos deixar filhos, ensinamentos, gestos, palavras, exemplos, lembranças e pequenas sementes espalhadas pelo caminho.\n\nSomos como pés que caminham por longas estradas, carregando milhares de cicatrizes. Cada uma delas conta uma história. Algumas nasceram de quedas; outras, de batalhas; outras ainda, de escolhas que gostaríamos de ter feito de maneira diferente.\n\nMas são justamente essas marcas que mostram que continuamos caminhando.\n\nUm pé sem cicatrizes talvez conte apenas que nunca enfrentou pedras.\n\nUm pé marcado revela que já passou por elas.\n\nE, mesmo ferido, continuou.\n\nPor isso, talvez não devêssemos olhar para nossas cicatrizes apenas como lembranças de nossas derrotas. Algumas são testemunhos da nossa resistência.\n\nPorque aquilo que nos esmagou nem sempre conseguiu nos destruir.\n\nÀs vezes, apenas abriu a terra.\n\nE foi nessa terra que nossa semente encontrou espaço para nascer novamente.\n\nSomos grãos, somos sementes, somos frutos.\n\nCaímos, somos feridos, recomeçamos.\n\nE, enquanto houver dentro de nós uma semente capaz de germinar, a vida', 3, FALSE, TIMESTAMPTZ '2026-10-03T15:44:26.559194+00:00', 2);

INSERT INTO public.poems (id, title, content, position, is_example, created_at, view_count)
VALUES (16, E'👑 A RAINHA INVISÍVEL DOS FRUTOS', E'Uma semente caiu no solo.\nTrazia dentro de si sua vocação:\nseria uma árvore de frutos.\nPoderia ter sido outra,\nmas a terra já sabia.\nO chão ofereceu o essencial.\nAs raízes sugaram água, minerais,\nelementos invisíveis que se transformam\nem vida, código, função.\nAli começava o trabalho silencioso.\nA árvore cresceu.\nGerou frutos.\nE o que chamamos de alimento\né apenas uma longa conversa\nentre a matéria e o mundo.\nSe ampliássemos um fruto milhares de vezes,\nveríamos primeiro moléculas,\ndepois átomos,\ndepois partículas girando em silêncio.\nMais fundo ainda,\nvibrações invisíveis sustentando tudo.\nFoi então que a Rainha falou.\nEla não usava coroa.\nHabitava o intervalo entre as coisas.\nDisse que cada fruto possui uma guardiã invisível:\numa presença que percorre a natureza\nderramando densidade, textura e sabor.\nÉ por isso que alguns frutos são cremosos.\nOutros guardam o sol em gomos.\nCada alimento carrega uma identidade.\nMas a Rainha estava cansada.\nContou que hoje seu trabalho pesa mais.\nO solo foi ferido.\nAs chuvas, alteradas.\nO calor, excessivo.\nAs terras, enfraquecidas.\nPor isso existem os limpadores invisíveis —\nmicrovidas que retiram impurezas,\nsalvam o que ainda pode ser salvo.\nSem eles, a fome seria maior.\nMesmo assim, a produção já nasce cansada.\n— Se dependesse de nós — disse ela —\nos alimentos seriam mais puros,\nmais vivos,\nmais verdadeiros.\nExplicou que toda matéria\ndepende do mundo que não se vê.\nAli está a maior organização que existe:\nnutrir, sustentar, manter o invisível em equilíbrio.\nQuando alguém passa fome,\nsão elas — as guardiãs silenciosas —\nque mais sofrem.\nPorque sabem que poderiam nutrir,\nse fossem ouvidas.\nSomos nós que alimentamos tudo:\nas flores, para que exalem perfume;\nas abelhas, para que façam mel;\nos pássaros, para que levem sementes;\nos animais;\no próprio ser humano.\nE ainda assim há guerra.\nForças que desejam empobrecer o solo,\nenfraquecer a vida,\nesvaziar a esperança.\nEssas forças são combatidas todos os dias\npelo cuidado,\npela escolha,\npelo amor.\nUma fruta que apodrece no galho foi atacada.\nMas a planta que resiste venceu.\nAli, a rainha do bem permaneceu.\nAntes de se calar, ela disse:\n— Queria que o bem se multiplicasse como sementes.\nAssim eu trabalharia mais feliz.\nE depois completou, serena:\n— Mas sou feliz mesmo assim.\nSou verdade.\nSomos a soma do bem da terra.\nSomos o alimento que ela gera.\nSomos o suco do amor.', 2, FALSE, TIMESTAMPTZ '2026-10-05T19:44:32.997238+00:00', 0);

INSERT INTO public.poems (id, title, content, position, is_example, created_at, view_count)
VALUES (17, E'🌅 Diálogo entre o Dia e a Noite', E'A noite provocou o dia:\n— Um dia vou te possuir.\nApagarei teu brilho\ne farei de ti apenas escuridão.\nO dia respondeu com calma:\n— Nem só de luz vivem\naqueles que nos admiram.\nQuando tu chegas\ne tua sombra me envolve,\nnão destróis minha presença —\napenas revelas outros brilhos.\nÉ na tua escuridão\nque nascem as estrelas,\nluzes pequenas\nque despertam os corações.\nPor isso, não te orgulhes\nnem te diminua.\nTu também és necessária,\npois sem a noite\no céu não mostraria\nsua infinita constelação.\nE a escuridão silenciou,\ncompreendendo enfim\nque até as estrelas\nsão luz dentro dela.', 1, FALSE, TIMESTAMPTZ '2026-10-05T20:12:05.47625+00:00', 1);

INSERT INTO public.poems (id, title, content, position, is_example, created_at, view_count)
VALUES (18, E'As Portas que o Horizonte Abre', E'Ao emigrar, o homem transfere consigo muito mais do que um passaporte.\nLeva suas raízes, suas lembranças, seus costumes, suas palavras e tudo aquilo que aprendeu a chamar de casa.\nDeixa para trás lugares conhecidos, rostos familiares e tradições que talvez tenham atravessado gerações.\nNão é uma decisão pequena.\nÉ preciso coragem para fechar uma porta sem saber exatamente o que encontraremos depois dela.\nDentro de cada imigrante existem cicatrizes.\nAlgumas nasceram da saudade. Outras, das dificuldades. E algumas talvez nunca sejam vistas por ninguém.\nMas mesmo carregando suas marcas, ele continua.\nAté a Lua faz seu passeio pelo céu.\nNão sabemos qual é o seu ponto favorito, nem se ela deseja permanecer sempre no mesmo lugar.\nTalvez a própria natureza nos ensine que existir também é movimentar-se.\nA cada escolha que fazemos, abrimos uma porta.\nA cada porta aberta, descobrimos um ambiente que antes não conhecíamos.\nE, quando atravessamos essa porta, outras aparecem.\nAlgumas conduzem a lugares que desejávamos encontrar.\nOutras nos levam a caminhos que jamais imaginamos percorrer.\nHá portas que se abrem com facilidade.\nHá outras que parecem não possuir maçaneta.\nNessas, é preciso procurar.\nTalvez empurrar.\nTalvez esperar.\nTalvez construir uma nova passagem.\nPorque a vida raramente entrega todos os caminhos prontos.\nSe cruzarmos os braços diante de uma janela, podemos perceber que existe um espaço lá fora nos chamando.\nO vento entra.\nA luz muda.\nO horizonte permanece.\nE alguma coisa dentro de nós pergunta:\n— O que existe depois daqui?\nFoi assim que o homem atravessou desertos.\nSubiu montanhas.\nEntrou em florestas.\nNavegou mares desconhecidos.\nObservou o céu tentando compreender as estrelas.\nDesceu às profundezas da Terra.\nOlhou através de lentes para descobrir mundos minúsculos.\nE apontou máquinas para o espaço para descobrir mundos que os olhos jamais poderiam alcançar.\nCada descoberta nasceu de uma pergunta.\nCada pergunta abriu uma porta.\nE cada porta revelou outra pergunta.\nTalvez essa seja uma das maiores aventuras da humanidade:\nnunca chegarmos ao fim do caminho.\nQuando alguém alcança determinado ponto, outro começa a caminhar a partir dali.\nO conhecimento não precisa terminar em quem o encontrou.\nPode ser deixado como uma ponte para quem virá depois.\nFoi assim que uma descoberta chamou outra.\nUma planta revelou um segredo.\nUm cientista encontrou uma possibilidade.\nUm médico procurou uma solução.\nUm inventor imaginou uma máquina.\nUm viajante encontrou uma terra.\nUm homem olhou para o céu e perguntou se estaríamos realmente sozinhos.\nE assim surgiram remédios para necessidades que antes pareciam sem solução, tecnologias que aproximaram distâncias e conhecimentos que mudaram a maneira como enxergamos o mundo.\nMas a aventura humana não está apenas nas grandes descobertas.\nEstá também naquele que atravessa uma fronteira em busca de trabalho.\nNa mãe que muda de cidade para dar aos filhos uma oportunidade.\nNo jovem que abandona o medo para aprender uma profissão.\nNa pessoa que recomeça depois de perder quase tudo.\nTodos eles estão abrindo portas.\nTodos estão procurando alguma coisa.\nE talvez ninguém saiba exatamente onde terminará sua estrada.\nO horizonte possui essa característica:\nquanto mais caminhamos em sua direção, mais ele parece se afastar.\nTalvez seja por isso que continuamos.\nNão porque sabemos onde chegaremos, mas porque ainda existem lugares que não conhecemos.\nAinda existem perguntas sem resposta.\nAinda existem caminhos que ninguém percorreu.\nAinda existem sementes esperando uma terra.\nAinda existem ideias esperando alguém que tenha coragem de pensá-las.\nE existe dentro do ser humano uma inquietação que parece não aceitar o limite do conhecido.\nQueremos saber.\nQueremos descobrir.\nQueremos compreender.\nQueremos criar.\nQueremos chegar um pouco mais longe.\nTalvez seja essa inquietação que tenha levado o homem a deixar sua primeira morada e procurar novos lugares para viver.\nTalvez seja a mesma força que hoje o leva a olhar para outros mundos.\nMudam as estradas.\nMudam os instrumentos.\nMudam as fronteiras.\nMas permanece a mesma pergunta:\no que existe depois do horizonte?\nTalvez nunca descubramos tudo.\nE talvez seja justamente isso que torna a vida uma aventura.\nPorque, enquanto houver uma porta para abrir, uma janela para atravessar, uma estrada para seguir ou um horizonte chamando,\no homem continuará caminhando.\nE cada passo deixará uma pequena marca no caminho, para que outro, algum dia, possa chegar até ali\ne continuar de onde ele parou.', 0, FALSE, TIMESTAMPTZ '2026-10-06T15:33:37.517596+00:00', 4);

